    public static func command(id: Int) -> LegacyCommand? { all.first { $0.id == id } }
    public static func commands(in group: String) -> [LegacyCommand] { all.filter { $0.group == group } }
    public static var groups: [String] { var seen: [String] = []; for c in all where !seen.contains(c.group) { seen.append(c.group) }; return seen }
    public static func count(_ status: LegacyCommandStatus) -> Int { all.filter { $0.status == status }.count }
    /// JSON-ready summary used by `--legacy-inventory` (CI smoke) and the in-app inventory view.
    public static func summary() -> [String: Any] {
        var statuses: [String: Int] = [:]
        for status in LegacyCommandStatus.allCases { statuses[status.rawValue] = count(status) }
        var entries: [[String: Any]] = []
        for c in all {
            var entry: [String: Any] = [:]
            entry["id"] = c.id; entry["group"] = c.group; entry["path"] = c.path; entry["label"] = c.label; entry["handler"] = c.handler
            entry["status"] = c.status.rawValue; entry["mac"] = c.macEquivalent; entry["reason"] = c.reason
            entries.append(entry)
        }
        let barCount = all.filter { menuBarGroups.contains($0.group) }.count
        var result: [String: Any] = [:]
        result["commands"] = all.count; result["menu_bar_commands"] = barCount; result["models"] = LegacyModelCatalog.all.count
        result["statuses"] = statuses; result["entries"] = entries
        return result
    }
}
